  trackCliCommandCompleted(
    data: {
      command: string;
      ok: boolean;
      exitCode: number;
      errorCode?: string;
      isRecoverable?: boolean;
      serverUnavailableReason?: ServerUnavailableReason;
      durationMs: number;
      callerAgent?: string;
      callerModel?: string;
      callerAgentSource?: 'handoff' | 'env';
      callerRunId?: string;
      designContextKind?: DesignContextKind;
      source?: 'cli' | 'mcp';
      error?: unknown;
    } & VariantContextMetadata &
      BrowserMetadata &
      VerificationMetadata,
  ): void {
    if (
      data.errorCode === 'MCP_REMOVED' &&
      !getConfigManager().claimMcpRemovedTelemetryWindow()
    ) {
      return;
    }
    this.track('cli_command_completed', {
      command: data.command,
      ok: data.ok,
      exit_code: data.exitCode,
      error_code: data.errorCode,
      is_recoverable: data.isRecoverable,
      server_unavailable_reason: data.serverUnavailableReason,
      ...(data.command === 'mcp'
        ? failureReasonProperties(data.error)
        : failureReasonCodeProperties(data.error)),
      duration_ms: data.durationMs,
      caller_agent: data.callerAgent,
      caller_model: data.callerModel,
      caller_agent_source: data.callerAgentSource,
      caller_run_id: data.callerRunId,
      verification_outcome: data.verificationOutcome,
      verification_check_count: data.verificationCheckCount,
      verification_duration_ms: data.verificationDurationMs,
      design_context_kind: data.designContextKind,
      design_context_kinds: data.contextKinds,
      context_image_count: data.contextImageCount,
      reference_page_count: data.referencePageCount,
      reference_video_count: data.referenceVideoCount,
      browser_action: data.browserAction,
      browser_reason: data.browserReason,
      source: data.source ?? 'cli',
      is_product_use: !LIFECYCLE_CLI_COMMANDS.has(data.command),
    });
  }

