  captureException(error: unknown, context: string): void {
    if (!this.isEnabled || !this.posthog || getTelemetryMode() !== 'full')
      return;

    try {
      this.posthog.captureException(error, this.distinctId, {
        context,
        source: this.defaultSource,
        telemetry_version: TELEMETRY_VERSION,
        rivet_version: RIVET_VERSION,
        platform: process.platform,
        node_version: process.version,
      });
      log.debug(`Captured exception in context: ${context}`);
    } catch (captureError) {
      log.debug('Failed to capture exception:', captureError);
    }
  }

