  async flush(): Promise<void> {
    if (this.posthog) {
      try {
        await this.posthog.flush();
        log.debug('Telemetry flush complete');
      } catch (error) {
        log.debug('Error during telemetry flush:', error);
      }
    }
  }

  async shutdown(timeoutMs?: number): Promise<void> {
    if (this.posthog) {
      const client = this.posthog;
      this.posthog = null;
      try {
        await client.shutdown(timeoutMs);
        log.debug('Telemetry shutdown complete');
      } catch (error) {
        log.debug('Error during telemetry shutdown:', error);
      }
    }
  }
